public static int findLargestSubstring(List<String> strings) {
        // Initialize a list to store the longest common substring
        List<String> longestCommonSubstring = new ArrayList<>();

        // Iterate over the list of strings
        for (int i = 0; i < strings.size(); i++) {
            for (int j = i + 1; j < strings.size(); j++) {
                // Find the longest common substring between the current string and the remaining strings
                List<String> commonSubstring = findLongestCommonSubstring(strings.get(i), strings.get(j));

                // If the current longest common substring is longer than the previous one, update it
                if (commonSubstring.size() > longestCommonSubstring.size()) {
                    longestCommonSubstring = commonSubstring;
                }
            }
        }

        // Return the length of the longest common substring
        return longestCommonSubstring.size();
    }

