public int findLargestSubstring(List<String> strings) {
    if (strings.size() <= 1) {
        return strings.size();
    }

    List<String> revStrings = new ArrayList<>(strings);
    for (int i = 0; i < revStrings.size(); i++) {
        revStrings.set(i, new StringBuilder(revStrings.get(i)).reverse().toString());
    }

    int maxLen = 0;
    String maxStr = null;
    for (String s : strings) {
        for (String r : revStrings) {
            int len = Math.max(s.length(), r.length());
            if (len > maxLen && (s.contains(r) || r.contains(s))) {
                maxLen = len;
                maxStr = s;
            }
        }
    }

    return maxLen;
}

