public int findLargestSubstring(List<String> strings) {
    // Create a set of all substrings for each string
    Set<String> substrings = new HashSet<>();
    for (String str : strings) {
        for (int i = 0; i < str.length(); i++) {
            substrings.add(str.substring(i));
        }
    }

    // Find the largest substring that is a substring of all strings
    int largestSubstringLength = 0;
    for (String str : substrings) {
        if (strings.stream().allMatch(s -> s.contains(str))) {
            largestSubstringLength = Math.max(largestSubstringLength, str.length());
        }
    }

    return largestSubstringLength;
}

