public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    Set<Integer> depositLocations = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                int location = i * grid[i].length + j;
                if (!depositLocations.contains(location)) {
                    numDeposits++;
                    depositLocations.add(location);
                }
            }
        }
    }
    return numDeposits;
}

