public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a boolean array to keep track of visited n-tersections
  boolean[] visited = new boolean[n];
  // Initialize a queue to do a BFS search
  Queue<Integer> queue = new LinkedList<>();
  // Mark the starting n-tersection as visited and add it to the queue
  visited[start[0]] = true;
  queue.add(start[0]);

  while (!queue.isEmpty()) {
    // Dequeue the first n-tersection from the queue
    int currX = queue.poll();
    int currY = visited[currX];

    // Check if we have reached the ending n-tersection, if so return the result
    if (currX == end[0] && currY == end[1]) {
      return "can be travelled";
    }

    // Loop through all the possible paths from the current n-tersection
    for (int i = 0; i < paths.length; i++) {
      // Get the adjacent n-tersection coordinates
      int nextX = paths[i][0];
      int nextY = paths[i][1];

      // Check if the adjacent n-tersection is not visited and not out of bounds
      if (!visited[nextX] && nextX >= 0 && nextY >= 0 && nextX < n && nextY < n) {
        // Mark the adjacent n-tersection as visited and add it to the queue
        visited[nextX] = true;
        queue.add(nextX);
      }
    }
  }

  // If we have visited all the n-tersections and did not reach the ending n-tersection,
  // Then return the result that the maze cannot be travelled
  return "cannot be travelled";
}

