public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < chars.length; i++) {
        sb.append(chars[i]);
        if (chars[i] > chars[i-1]) {
            break;
        }
    }
    for (int i = chars.length-1; i >= 0; i--) {
        sb.append(chars[i]);
        if (chars[i] < chars[i+1]) {
            break;
        }
    }
    return sb.toString();
}

