public int minCostClimbingStairs(int[] cost) {
    // Initialize the minimum cost to reach each step
    int[] minCost = new int[cost.length];
    // Initialize the last step to be the cost to reach the top
    minCost[cost.length - 1] = cost[cost.length - 1];
    // Initialize the second last step to be the cost to reach the top
    minCost[cost.length - 2] = cost[cost.length - 2];
    // Loop through the remaining steps in reverse order
    for (int i = cost.length - 3; i >= 0; i--) {
        // Calculate the minimum cost to reach the current step
        minCost[i] = cost[i] + Math.min(minCost[i + 1], minCost[i + 2]);
    }
    // Return the minimum cost to reach the bottom step
    return minCost[0];
}

