public int minCostClimbingStairs(int[] cost) {
  int n = cost.length;
  if (n == 1 || n == 2) {
    return 0;
  }
  int[] dp = new int[n + 1];
  dp[0] = 0;
  dp[1] = 0;
  for (int i = 2; i <= n; i++) {
    dp[i] = Math.min(dp[i - 1], dp[i - 2]);
  }
  return dp[n];
}

