    // Create a map to store the unique Morse code representations
    Map<String, Integer> morseRepresentations = new HashMap<>();

    // Loop over each word in the input array
    for (String word : words) {
        // Convert the word to its Morse code representation
        String morseCode = getMorseCode(word);

        // Check if the Morse code representation is already in the map
        if (!morseRepresentations.containsKey(morseCode)) {
            // If not, add it to the map and increment the count
            morseRepresentations.put(morseCode, 1);
        } else {
            // If it is already in the map, increment the count
            morseRepresentations.put(morseCode, morseRepresentations.get(morseCode) + 1);
        }
    }

    // Return the number of unique Morse code representations
    return morseRepresentations.size();
}

