public boolean hasAllCodes(String s, int k) {
    // check if the length of s is greater than or equal to k
    if (s.length() < k) {
        return false;
    }

    // initialize a set to store the binary strings of length k
    Set<String> binaryStrings = new HashSet<>();

    // loop through each substring of length k in s
    for (int i = 0; i <= s.length() - k; i++) {
        String binaryString = s.substring(i, i + k);

        // check if the binary string is valid
        if (!isBinaryString(binaryString)) {
            return false;
        }

        // add the binary string to the set
        binaryStrings.add(binaryString);
    }

    // check if the set contains all possible binary strings of length k
    return binaryStrings.size() == (int) Math.pow(2, k);
}

