public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (n == 0 || n < k) {
        return false;
    }
    int count = 0;
    for (int i = 0; i <= n - k; i++) {
        String substr = s.substring(i, i + k);
        if (substr.equals(Integer.toBinaryString(count))) {
            count++;
        }
    }
    return count == (1 << k);
}

