public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }
  int minOperations = 0;
  while (!allEqual(arr)) {
    int x = -1, y = -1;
    int minDiff = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        int diff = arr[i] - arr[j];
        if (diff < minDiff) {
          minDiff = diff;
          x = i;
          y = j;
        }
      }
    }
    arr[x] -= 1;
    arr[y] += 1;
    minOperations++;
  }
  return minOperations;
}

