public int maxUniqueSplit(String s) {
    // Initialize a set to store the unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();
    // Initialize a variable to store the maximum number of unique substrings
    int maxUniqueSubstrings = 0;
    // Iterate over the characters in the string
    for (int i = 0; i < s.length(); i++) {
        // Get the substring from the current character to the end of the string
        String substr = s.substring(i);
        // If the substring is not already in the set, add it
        if (!uniqueSubstrings.contains(substr)) {
            uniqueSubstrings.add(substr);
            // Update the maximum number of unique substrings
            maxUniqueSubstrings = Math.max(maxUniqueSubstrings, uniqueSubstrings.size());
        }
    }
    // Return the maximum number of unique substrings
    return maxUniqueSubstrings;
}

