    int n = mat[0].length;
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int count = 1;
                int row = i;
                int col = j;

                while (row > 0 && mat[row - 1][col] == 1) {
                    count++;
                    row--;
                }

                while (row < m - 1 && mat[row + 1][col] == 1) {
                    count++;
                    row++;
                }

                while (col > 0 && mat[row][col - 1] == 1) {
                    count++;
                    col--;
                }

                while (col < n - 1 && mat[row][col + 1] == 1) {
                    count++;
                    col++;
                }

                max = Math.max(max, count);
            }
        }
    }

    return max;
}

