    PriorityQueue<Integer> heap = new PriorityQueue<>();
    heap.add(1);

    // Iterate until we find the nth ugly number
    for (int i = 0; i < n; i++) {
        // Get the current smallest multiple
        int current = heap.poll();

        // Add the next multiples of 2, 3, and 5 to the heap
        heap.add(current * 2);
        heap.add(current * 3);
        heap.add(current * 5);
    }

    // Return the last smallest multiple, which is the nth ugly number
    return heap.poll();
}

