public static int minPerfectSquareSum(int n) {
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        perfectSquares.add(i * i);
    }
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 0; j < perfectSquares.size(); j++) {
            if (perfectSquares.get(j) <= i) {
                dp[i] = Math.min(dp[i], dp[i - perfectSquares.get(j)] + 1);
            }
        }
    }
    return dp[n];
}

