    StringBuilder result = new StringBuilder(s.length());
    String[] words = s.split(" ");
    for (int i = 0; i < words.length; i++) {
        char[] wordChars = words[i].toCharArray();
        for (int j = wordChars.length - 1; j >= 0; j--) {
            result.append(wordChars[j]);
